// urlsplit-ish helpers replicating CPython urlunsplit + furl composition
const USES_NETLOC = new Set(['','ftp','http','gopher','nntp','telnet','imap','wais','file','mms','https','shttp',
 'snews','prospero','rtsp','rtspu','rsync','svn','svn+ssh','sftp','nfs','git','git+ssh','ws','wss','itms-services']);
const DEFAULT_PORTS = {ftp:21, ssh:22, telnet:23, smtp:25, http:80, ws:80, pop3:110, imap:143, https:443, wss:443, ldap:389, ldaps:636, rtsp:554, git:9418, ftps:990, imaps:993, pop3s:995};

function urlunsplit(scheme, netloc, url, query, fragment){
  // netloc may be null
  if (netloc || (scheme && USES_NETLOC.has(scheme) && url.slice(0,2) !== '//')) {
    if (url && url[0] !== '/') url = '/' + url;
    url = '//' + (netloc || '') + url;
  }
  if (scheme) url = scheme + ':' + url;
  if (query) url = url + '?' + query;
  if (fragment) url = url + '#' + fragment;
  return url;
}

// furl netloc property
function furlNetloc(host, username, password, port, scheme){
  let userpass = encodeURIComponent(username || '');
  if (password !== null && password !== undefined) userpass += ':' + encodeURIComponent(password);
  if (userpass || (username !== null && username !== undefined)) userpass += '@';
  let netloc = host;                       // may be null
  if (port && port !== DEFAULT_PORTS[scheme]) netloc = (netloc || '') + ':' + port;
  if (userpass) netloc = userpass + (netloc || '');
  return netloc;
}

function buildUrl(parts){
  const {scheme, host, username, password, port, path, query, fragment} = parts;
  const netloc = furlNetloc(host, username, password, port, scheme);
  let url = urlunsplit(scheme === null ? '' : scheme, netloc, path, query, fragment);
  if (scheme === '') url = ':' + url;
  if (netloc === '' && scheme === null) url = '//' + url;
  return url;
}
module.exports = {buildUrl, furlNetloc, urlunsplit};
