new='''function fragStr(raw){
  if(raw===null) return '';
  const i=raw.indexOf('?');
  if(i<0) return raw;
  const rest=raw.slice(i+1);
  if(!rest.includes('=')) return raw;   // '?' is part of the fragment path
  const path=raw.slice(0,i);
  if(path==='') return rest;            // separator suppressed when path empty
  return path+'?'+rest;
}'''
